#include <iostream>
#include <set>
#include <bitset>
using namespace std;

int main() {
    set<int> A = {1, 2, 3, 4, 5};
    set<int> B = {3, 4, 5, 6, 7};

    cout << "集合 A 的大小: " << A.size() << endl;
    cout << "3 是否在 A 中: " << (A.count(3) ? "是" : "否") << endl;
    cout << "8 是否在 A 中: " << (A.count(8) ? "是" : "否") << endl;

