}

#include <iostream>
#include <set>
#include <bitset>
using namespace std;

int main() {
    set<int> A = {1, 2, 3, 4, 5};
    set<int> B = {3, 4, 5, 6, 7};

    set<int> unionSet = A;
    for (int x : B) unionSet.insert(x);
    cout << "并集大小: " << unionSet.size() << endl;

    set<int> interSet;
    for (int x : A) if (B.count(x)) interSet.insert(x);
    cout << "交集大小: " << interSet.size() << endl;

    set<int> diffSet;
    for (int x : A) if (!B.count(x)) diffSet.insert(x);
    cout << "差集 A\\B 大小: " << diffSet.size() << endl;

    bitset<8> bs1(string("00111110"));
    bitset<8> bs2(string("01111000"));
    cout << "并集: " << (bs1 | bs2) << endl;
    cout << "交集: " << (bs1 & bs2) << endl;
    cout << "对称差: " << (bs1 ^ bs2) << endl;

    int total = 30, likeMath = 15, likePhysics = 12, likeBoth = 5;
    int likeEither = likeMath + likePhysics - likeBoth;
    int likeNeither = total - likeEither;
    cout << "至少喜欢一门: " << likeEither << endl;
    cout << "都不喜欢: " << likeNeither << endl;

    return 0;
}

#include <iostream>
using namespace std;

int main() {
    bool p = true, q = false;

    cout << "p && q (与): " << (p && q) << endl;
    cout << "p || q (或): " << (p || q) << endl;
    cout << "!p (非): " << (!p) << endl;
    cout << "!p || q (蕴含 p->q): " << (!p || q) << endl;
    cout << "p == q (等价): " << (p == q) << endl;

    int x = 7;
    bool isPositive = (x > 0);
    bool isEven = (x % 2 == 0);
    cout << x << " 是正数且是偶数: " << (isPositive && isEven) << endl;
    cout << x << " 是正数或是偶数: " << (isPositive || isEven) << endl;

    int age = 15;
    bool canRide = (age >= 12) && (age <= 60);
    cout << age << " 岁可以乘坐: " << canRide << endl;

    return 0;
}

#include <iostream>
#include <vector>
using namespace std;

int main() {
    bool p = true, q = false;
    cout << "not (p and q) = " << (!(p && q)) << endl;
    cout << "(not p) or (not q) = " << ((!p) || (!q)) << endl;
    cout << "两者相等: " << ((!(p && q)) == ((!p) || (!q))) << endl;

    cout << "not (p or q) = " << (!(p || q)) << endl;
    cout << "(not p) and (not q) = " << ((!p) && (!q)) << endl;
    cout << "两者相等: " << ((!(p || q)) == ((!p) && (!q))) << endl;

    vector<int> arr = {3, 7, 12, -5, 8};
    bool allPositive = true;
    for (int x : arr) if (x <= 0) { allPositive = false; break; }
    bool existsNonPositive = false;
    for (int x : arr) if (x <= 0) { existsNonPositive = true; break; }
    cout << "全部为正: " << allPositive << endl;
    cout << "存在非正: " << existsNonPositive << endl;
    cout << "互为否定: " << (allPositive != existsNonPositive) << endl;

    return 0;
}

#include <iostream>
using namespace std;

int main() {
    cout << "p q | p&&q p||q !p p->q" << endl;
    cout << "----+--------------------" << endl;
    for (int p = 0; p <= 1; p++) {
        for (int q = 0; q <= 1; q++) {
            bool bp = p, bq = q;
            bool and_ = bp && bq;
            bool or_ = bp || bq;
            bool not_ = !bp;
            bool imp = !bp || bq;
            cout << p << " " << q << " |  "
                 << and_ << "    " << or_ << "   "
                 << not_ << "   " << imp << endl;
        }
    }

    cout << "\n验证 p->q 等价于 !p||q:" << endl;
    bool isTautology = true;
    for (int p = 0; p <= 1; p++) {
        for (int q = 0; q <= 1; q++) {
            bool bp = p, bq = q;
            bool imp = (!bp) || bq;
            bool contraPos = (!bq) || (!(!bp));
            if (imp != contraPos) isTautology = false;
        }
    }
    cout << "永真式验证: " << (isTautology ? "是" : "否") << endl;

    cout << "\n验证德摩根定律:" << endl;
    bool demorgan = true;
    for (int p = 0; p <= 1; p++) {
        for (int q = 0; q <= 1; q++) {
            bool bp = p, bq = q;
            if (!(bp && bq) != (!bp || !bq)) demorgan = false;
        }
    }
    cout << "德摩根定律成立: " << (demorgan ? "是" : "否") << endl;

    return 0;
}

#include <iostream>
using namespace std;

int main() {
    cout << "判断 x=2 与 x 是偶数的关系:" << endl;
    int x = 2;
    bool p = (x == 2);
    bool q = (x % 2 == 0);
    cout << "x=2 -> x 是偶数: " << ((!(x == 2)) || (x % 2 == 0)) << endl;
    cout << "x 是偶数 -> x=2: " << ((!(x % 2 == 0)) || (x == 2));
    cout << " (x=4 时为假，所以不成立)" << endl;

    cout << "\n判断 n%4==0 与 n%2==0 的关系:" << endl;
    bool sufficient = true, necessary = false;
    for (int n = 0; n < 100; n++) {
        if (n % 4 == 0 && n % 2 != 0) sufficient = false;
    }
    for (int n = 0; n < 100; n++) {
        if (n % 2 == 0 && n % 4 != 0) necessary = true;
    }
    cout << "n%4==0 是 n%2==0 的充分条件: " << sufficient << endl;
    cout << "n%4==0 是 n%2==0 的必要条件: " << (!necessary ? "是" : "否") << endl;
    cout << "结论: 充分不必要条件" << endl;

    return 0;
}

#include <iostream>
using namespace std;

bool isRationalSquareRootOfTwo(int maxDenom) {
    for (int q = 1; q <= maxDenom; q++) {
        for (int p = 1; p <= maxDenom; p++) {
            if (p * p == 2 * q * q) {
                return true;
            }
        }
    }
    return false;
}

bool hasTwoConsecutiveNonPrimes(int n) {
    int consecutive = 0;
    for (int i = 2; i <= n; i++) {
        bool isPrime = true;
        for (int j = 2; j * j <= i; j++) {
            if (i % j == 0) { isPrime = false; break; }
        }
        if (!isPrime) {
            consecutive++;
            if (consecutive >= 2) return true;
        } else {
            consecutive = 0;
        }
    }
    return false;
}

