#include <iostream>
#include <vector>
using namespace std;

int main() {
    cout << "构造：对于任意 n>=3，存在 n 个连续合数" << endl;
    cout << "构造方案：(n+1)! + 2, (n+1)! + 3, ..., (n+1)! + (n+1)" << endl;
    int n = 5;
    long long factorial = 1;
    for (int i = 2; i <= n + 1; i++) factorial *= i;
    cout << n + 1 << "! = " << factorial << endl;
    cout << "连续 " << n << " 个合数: ";
    for (int i = 2; i <= n + 1; i++) {
        cout << factorial + i << "(" << (factorial + i) << "/" << i
             << "=" << (factorial + i) / i << ") ";
    }
    cout << endl;

    cout << "\n构造：1 到 n 的排列，使得相邻两数之和为素数" << endl;
    vector<int> perm = {1, 2, 3, 4};
    do {
        bool valid = true;
        for (int i = 0; i < 3; i++) {
            int sum = perm[i] + perm[i + 1];
            bool isPrime = true;
            for (int j = 2; j * j <= sum; j++) {
                if (sum % j == 0) { isPrime = false; break; }
            }
            if (!isPrime) { valid = false; break; }
        }
        if (valid) {
            cout << "找到排列: ";
            for (int x : perm) cout << x << " ";
            cout << endl;
            break;
        }
    } while (next_permutation(perm.begin(), perm.end()));

    return 0;
}

#include <iostream>
using namespace std;

long long fib[51];
long long factorial[21];

int main() {
    fib[1] = 1;
    fib[2] = 1;
    for (int i = 3; i <= 50; i++) {
        fib[i] = fib[i - 1] + fib[i - 2];
    }
    cout << "斐波那契数列前 15 项:" << endl;
    for (int i = 1; i <= 15; i++) {
        cout << "F(" << i << ")=" << fib[i] << " ";
        if (i % 5 == 0) cout << endl;
    }

    factorial[0] = 1;
    for (int i = 1; i <= 20; i++) {
        factorial[i] = factorial[i - 1] * i;
    }
    cout << "\n阶乘验证 10!=" << factorial[10] << endl;

    cout << "\n证明 F(1)+F(2)+...+F(n) = F(n+2)-1:" << endl;
    long long sum = 0;
    for (int n = 1; n <= 15; n++) {
        sum += fib[n];
        cout << "n=" << n << ": sum=" << sum
             << ", F(" << n+2 << ")-1=" << fib[n + 2] - 1;
        cout << (sum == fib[n + 2] - 1 ? " ✓" : " ✗") << endl;
    }

    return 0;
}

#include <iostream>
using namespace std;

int main() {
    cout << "验证 1+2+...+n = n(n+1)/2" << endl;
    long long sum = 0;
    for (int n = 1; n <= 20; n++) {
        sum += n;
        long long formula = (long long)n * (n + 1) / 2;
        cout << "n=" << n << ": sum=" << sum
             << ", n(n+1)/2=" << formula
             << (sum == formula ? " ✓" : " ✗") << endl;
    }

    cout << "\n验证 2^n > n+1 (n >= 2)" << endl;
    long long power = 1;
    for (int n = 1; n <= 20; n++) {
        power *= 2;
        if (n >= 2) {
            cout << "n=" << n << ": 2^n=" << power
                 << ", n+1=" << n + 1
                 << (power > n + 1 ? " ✓" : " ✗") << endl;
        }
    }

    cout << "\n验证 3 整除 n^3 - n" << endl;
    for (int n = 1; n <= 15; n++) {
        int val = n * n * n - n;
        cout << "n=" << n << ": n^3-n=" << val
             << ", mod 3=" << val % 3
             << (val % 3 == 0 ? " ✓" : " ✗") << endl;
    }

    return 0;
}
